  ON FUNCTION "public"."get_nearby_incidents"(double precision, double precision, text, public.vector, double precision, double precision, uuid)
  TO PUBLIC, "anon", "authenticated";

REVOKE ALL ON FUNCTION "public"."get_nearby_incidents"(double precision, double precision, text, public.vector, double precision, double precision, uuid) FROM "postgres";

GRANT EXECUTE ON FUNCTION "public"."get_nearby_incidents"(double precision, double precision, text, public.vector, double precision, double precision, uuid) TO "postgres";

GRANT EXECUTE ON FUNCTION "public"."get_nearby_incidents"(double precision, double precision, text, public.vector, double precision, double precision, uuid) TO "service_role";

GRANT EXECUTE ON FUNCTION "public"."rls_auto_enable"() TO PUBLIC, "anon", "authenticated";

REVOKE ALL ON FUNCTION "public"."rls_auto_enable"() FROM "postgres";

GRANT EXECUTE ON FUNCTION "public"."rls_auto_enable"() TO "postgres";

GRANT EXECUTE ON FUNCTION "public"."rls_auto_enable"() TO "service_role";

